const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Leipzig mining region (Neuseenland)
  const leipzigRegion = ee.Geometry.Rectangle([12.3, 51.2, 12.5, 51.4]);

  // 2. Define time ranges for April 1987 and April 2020
  const april1987 = ee.DateRange('1987-04-01', '1987-04-30');
  const april2020 = ee.DateRange('2020-04-01', '2020-04-30');

  // 3. Load JRC Monthly Water History dataset
  const jrcCollection = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory');

  // Filter for April 1987
  const water1987 = jrcCollection
    .filterDate(april1987.start(), april1987.end())
    .filterBounds(leipzigRegion)
    .first();

  // Filter for April 2020  
  const water2020 = jrcCollection
    .filterDate(april2020.start(), april2020.end())
    .filterBounds(leipzigRegion)
    .first();

  // 4. Check if images exist
  const count1987 = water1987 ? 1 : 0;
  const count2020 = water2020 ? 1 : 0;

  console.log(`April 1987 Images: ${count1987}`);
  console.log(`April 2020 Images: ${count2020}`);

  if (count1987 === 0 || count2020 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. Extract water pixels (value == 2)
  const waterMask1987 = water1987.eq(2); // 1 for water, 0 for non-water
  const waterMask2020 = water2020.eq(2);

  // 6. Count water pixels
  const stats1987 = waterMask1987.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: leipzigRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2020 = waterMask2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: leipzigRegion,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterArea1987 = stats1987.get('water').getInfo();
  const waterArea2020 = stats2020.get('water').getInfo();

  console.log(`1987 Water Pixel Sum: ${waterArea1987}`);
  console.log(`2020 Water Pixel Sum: ${waterArea2020}`);

  // 7. Check for valid pixels (C2)
  if (waterArea1987 === null || waterArea2020 === null) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 8. Validate results (C3)
  if (waterArea1987 === undefined || waterArea2020 === undefined ||
      isNaN(waterArea1987) || isNaN(waterArea2020)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 9. Compare and output final answer
  console.log(`Change: ${waterArea2020 - waterArea1987}`);

  if (waterArea2020 > waterArea1987) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
